        "other": "No"
      },
      "passage": {
        "title": "Important Factors",
        "quote": "contact rate ($\\beta$), recruitment rate ($\\varLambda$), the loss of protection for the vaccination rate ($\\theta$), and rate of progression from the exposed class to the infectious class ($\\gamma$) were the most important factors."
