        "parameter": "pi",
        "label": "Vaccination Rate",
        "lowEnd": "0.01",
        "highEnd": "0.3"
      },
      "watch": "s",
      "whatIf": {
        "prompt": "What if the vaccination rate was increased to 0.2?",
        "parameter": "pi",
        "value": 0.2
      },
      "difference": {
        "compartment": "s",
        "summary": "at",
        "at": 19.03,
        "time": 36,
        "relation": "lower",
        "by": 5
