        "prompt": "Will a higher vaccination rate result in fewer susceptible people over time?",
        "claimed": "Yes",
        "other": "No"
      },
      "passage": {
        "title": "Model Structure",
        "quote": "The total population is divided into six distinct compartments: susceptible $S(t)$, vaccinated $V(t)$, exposed $E(t)$, infectious $I(t)$, treated, $T(t)$ and recovered $R(t)$."
      },
      "carryForward": ""
    },
