      "prediction": {
        "prompt": "Will slowing down the treatment rate increase the number of infectious people?",
        "claimed": "Yes",
        "other": "No"
      },
      "passage": {
        "title": "Disease Persistence",
        "quote": "We obtained $\\mathscr{R}_0 = 2.67$ for the estimated model parameters, which are greater than one, indicating that the tuberculosis is continuously multiplying."
